function IO(thunk) {
  return { run: thunk };
}
function orElse(io, fallbackIo) {
  return IO(() => {
    try {
      return io.run();
    } catch (e) {
      return fallbackIo.run();
    }
  });
}

const risky = IO(() => { throw new Error('連線失敗'); });
const fallback = IO(() => '使用快取資料');

const safe = orElse(risky, fallback);

console.log(safe.run());

